/**
 * MINEFECT product catalogue — single typed source of truth.
 * Generated by merging the legacy catalog.js (FR) + catalog-en.js (EN) by id.
 * 7 categories · 12 subcategories · 43 products.
 */
export type Unit = 'PCE' | 'KG' | 'M';

export interface Product {
  id: string;
  name: { fr: string; en: string };
  description: { fr: string; en: string };
  image: string;
  unit: Unit;
  ref?: string;
}
export interface Subcategory {
  id: string;
  title: { fr: string; en: string };
  products: Product[];
}
export interface Category {
  id: string;
  title: { fr: string; en: string };
  description: { fr: string; en: string };
  image: string;
  subcategories: Subcategory[];
}

export const PLACEHOLDER_PRODUCT = '/assets/images/placeholders/product.png';

/** Products with no real photo render a branded placeholder + "Sur demande / On request" label. */
export const isPlaceholder = (p: Product): boolean => p.image === PLACEHOLDER_PRODUCT;

export const t = (v: { fr: string; en: string }, lang: Locale): string => v[lang];

