export const findCategory = (id: string): Category | undefined => CATALOG.find((c) => c.id === id);
export const findSubcategory = (cat: Category, id: string): Subcategory | undefined =>
  cat.subcategories.find((s) => s.id === id);

export const totalProducts = (): number =>
  CATALOG.reduce((a, c) => a + c.subcategories.reduce((b, s) => b + s.products.length, 0), 0);
